function restorePantryRecord(db,pantryId,amount){const row=db.query('SELECT * FROM pantry WHERE pantry_id=? LIMIT 1',[pantryId])[0];if(!row)return 0;const delta=Math.max(0,Number(amount)||0),next=(Number(row.quantity)||0)+delta;db.run('UPDATE pantry SET quantity=?,on_hand=?,status=? WHERE pantry_id=?',[next,next>0?'Yes':'No',next>0?'Active':'Out of Stock',pantryId]);return delta}
