function sourceInventoryPayloads(db,{sourceType='food',item={},servings=1,food_id=null,food_name='',unit='serving'}={}){
 const multiplier=Math.max(0,Number(servings)||0);
 if(sourceType==='food')return [{pantry_id:item.pantry_id||null,food_id:item.food_id||food_id||null,food_name:item.name||food_name||'',amount:multiplier,unit}];
 if(sourceType==='recipe'){
  const recipeId=item.recipe_id||item.meal_id||String(food_id||'').replace(/^recipe:/i,''),basis=recipeServingBasis((sql,params)=>db.query(sql,params),recipeId),preparedId=`recipe:${String(recipeId).replace(/^recipe:/i,'')}`;
  const prepared=db.query(`SELECT pantry_id,food_id,item,quantity,unit FROM pantry WHERE COALESCE(discontinued,0)=0 AND UPPER(food_id)=UPPER(?) ORDER BY id LIMIT 1`,[preparedId])[0];
  if(prepared)return [{pantry_id:prepared.pantry_id,food_id:preparedId,food_name:prepared.item||item.title||item.recipe_name||food_name,amount:multiplier*basis.size,unit:basis.unit}];
  return db.query('SELECT ingredient_id,ingredient_name,amount,unit,ingredient_type FROM recipes WHERE recipe_id=? ORDER BY id',[String(recipeId).replace(/^recipe:/i,'')]).flatMap(row=>String(row.ingredient_type||'food').toLowerCase()==='recipe'?sourceInventoryPayloads(db,{sourceType:'recipe',item:{recipe_id:row.ingredient_id},servings:multiplier*(Number(row.amount)||1)}):[{food_id:row.ingredient_id||null,food_name:row.ingredient_name,amount:multiplier*(Number(row.amount)||0),unit:row.unit||'serving'}])
 }
 if(sourceType==='meal'){const mealId=item.meal_id||item.meal_definition_id;return db.query('SELECT component_type,component_id,component_name,amount,unit FROM meal_components WHERE meal_id=? ORDER BY sort_order,id',[mealId]).flatMap(row=>sourceInventoryPayloads(db,{sourceType:String(row.component_type||'food').toLowerCase(),item:row.component_type==='recipe'?{recipe_id:row.component_id}:{food_id:row.component_id,name:row.component_name},servings:multiplier*(Number(row.amount)||1),food_id:row.component_id,food_name:row.component_name,unit:row.unit||'serving'}))}
 return [];
}
function applySourceInventoryConsumption(db,options={}){const totals=new Map(),payloads=sourceInventoryPayloads(db,options);for(const payload of payloads){const match=resolvePantryConsumption(db,payload);if(!match)continue;const adjustment=decrementResolvedPantry(db,payload);if(!adjustment.pantry_id||adjustment.pantry_delta<=0)throw new Error(`${payload.food_name||options.food_name||'Tracked food'} is tracked in Pantry, but its inventory could not be deducted.`);const existing=totals.get(adjustment.pantry_id);totals.set(adjustment.pantry_id,existing?{...adjustment,pantry_delta:existing.pantry_delta+adjustment.pantry_delta,before:existing.before,after:adjustment.after}:{...adjustment})}return [...totals.values()]}
function recordMealPantryAdjustments(db,mealId,sourceRecordId,adjustments=[]){for(const row of adjustments)db.run('INSERT OR REPLACE INTO meal_pantry_adjustments(meal_id,source_record_id,pantry_id,delta,before_json,after_json,created_at) VALUES (?,?,?,?,?,?,?)',[mealId,sourceRecordId||null,row.pantry_id,row.pantry_delta,JSON.stringify(row.before||null),JSON.stringify(row.after||null),new Date().toISOString()])}
function safeLegacyRestoreDelta(db,pantryId,storedDelta,fallback={}){const stored=Math.max(0,Number(storedDelta)||0);const match=resolvePantryConsumption(db,{pantry_id:pantryId,food_id:fallback.food_id,food_name:fallback.food_name,amount:fallback.amount||1,unit:fallback.unit||'serving'});const expected=Math.max(0,Number(match?.delta)||0);return expected>0?Math.min(stored,expected):stored}
function restoreMealPantryAdjustments(db,mealId,fallback=null){const rows=db.query('SELECT pantry_id,delta,before_json,after_json FROM meal_pantry_adjustments WHERE meal_id=?',[mealId]);if(rows.length){for(const row of rows){let before=null,after=null;try{before=JSON.parse(row.before_json||'null');after=JSON.parse(row.after_json||'null')}catch{}const current=db.query('SELECT * FROM pantry WHERE pantry_id=? LIMIT 1',[row.pantry_id])[0];const currentQty=Math.max(0,Number(current?.quantity)||0),afterQty=Math.max(0,Number(after?.quantity)||0);if(before&&after&&current&&Math.abs(currentQty-afterQty)<0.000001)restorePantrySnapshot(db,row.pantry_id,before);else restorePantryRecord(db,row.pantry_id,safeLegacyRestoreDelta(db,row.pantry_id,row.delta,fallback||{}))}db.run('DELETE FROM meal_pantry_adjustments WHERE meal_id=?',[mealId]);return rows.map(row=>({pantry_id:row.pantry_id,pantry_delta:safeLegacyRestoreDelta(db,row.pantry_id,row.delta,fallback||{})}))}if(fallback?.pantry_id&&Number(fallback.pantry_delta)){const delta=safeLegacyRestoreDelta(db,fallback.pantry_id,fallback.pantry_delta,fallback);restorePantryRecord(db,fallback.pantry_id,delta);return [{pantry_id:fallback.pantry_id,pantry_delta:delta}]}if(fallback?.food_id||fallback?.food_name){const match=resolvePantryConsumption(db,{food_id:fallback.food_id,food_name:fallback.food_name,amount:fallback.amount||1,unit:fallback.unit||'serving'});if(match&&match.delta>0){restorePantryRecord(db,match.row.pantry_id,match.delta);return [{pantry_id:match.row.pantry_id,pantry_delta:match.delta,reconstructed:true}]}}return []}
async function discoverRetailerImage(url){
 const value=String(url||'').trim();if(!value)return {status:'missing_link',image:''};
 if(/\.(?:png|jpe?g|webp|gif)(?:[?#].*)?$/i.test(value))return {status:'loaded',image:value};
 try{const response=await fetch(value,{mode:'cors',credentials:'omit',redirect:'follow'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const html=await response.text();const doc=new DOMParser().parseFromString(html,'text/html');const image=doc.querySelector('meta[property="og:image"],meta[name="twitter:image"],link[rel="image_src"]')?.content||doc.querySelector('meta[property="og:image"],meta[name="twitter:image"]')?.getAttribute('content')||doc.querySelector('link[rel="image_src"]')?.href||'';return image?{status:'loaded',image:new URL(image,response.url).href}:{status:'not_found',image:''}}
 catch(error){return {status:'blocked',image:'',error:error?.message||String(error)}}
}
