function pantryInventoryRows(rows=[]){
 const seen=new Set();
 return rows.filter(row=>{
  if(Number(row.discontinued)===1)return false;
  const sourceRecipe=String(row.source_recipe_id||'').trim();
  const foodId=String(row.food_id||'').trim();
  const isPreparedComposite=foodId.toLowerCase().startsWith('recipe:');
  const isEmbeddedRecipeComponent=Boolean(sourceRecipe)&&!isPreparedComposite&&foodId.toLowerCase()!==`recipe:${sourceRecipe}`.toLowerCase();
  if(isEmbeddedRecipeComponent)return false;
  const identity=String(row.pantry_id||row.id||`${foodId}:${row.item||''}:${row.location||''}:${row.expiration||''}`).toLowerCase();
  if(seen.has(identity))return false;
  seen.add(identity);
  return true;
 });
}
