 const move=e=>{if(!start.current)return;const dx=e.clientX-start.current.x,dy=e.clientY-start.current.y;if(Math.abs(dx)>8||Math.abs(dy)>8)moved.current=true;if(Math.abs(dx)>Math.abs(dy)){const maxRight=Math.max(180,width.current*.72),next=Math.max(-leftOpenWidth,Math.min(maxRight,dx)),threshold=Math.min(168,width.current*.48),ready=next>=threshold,wasReady=commitReadyRef.current;setOffset(next);setCommitReady(ready);if(ready&&!wasReady)libraryConsumptionTrace('commit-threshold',{label,offset:next,threshold})}};
