 const availability=buildAvailabilityIndex({pantryRows:optionalQuery(`SELECT p.*,f.name AS food_name,f.default_serving,f.unit AS food_unit,f.serving_description,f.servings_per_container AS food_servings_per_container FROM pantry p LEFT JOIN foods f ON UPPER(f.food_id)=UPPER(p.food_id)`),recipeRows:optionalQuery(`SELECT recipe_id,ingredient_type,ingredient_id,ingredient_name,amount,unit FROM recipes WHERE COALESCE(archived,0)=0`),mealComponents:optionalQuery(`SELECT meal_id,component_type,component_id,component_name,optional FROM meal_components`),mealDefinitions:optionalQuery(`SELECT meal_id,source_type,source_id,track_inventory FROM meal_definitions WHERE COALESCE(archived,0)=0`)});
 const savedMeals=optionalQuery(`SELECT *, 'meal' AS planner_source FROM meal_definitions WHERE COALESCE(archived,0)=0 AND COALESCE(source_type,'') NOT IN ('legacy_recipe','recipe') AND COALESCE(usage_designation,'standalone') IN ('standalone','both') ORDER BY category,title COLLATE NOCASE`).map(row=>{const snapshot=getMealNutrition(query,row.meal_id);return {...row,...(snapshot?.nutrition||{}),nutrition_known:snapshot?.nutrition_known??0,nutrition_issues:snapshot?.issues||[]}}).filter(row=>availability.itemAvailable(row));
 const standaloneFoods=optionalQuery(`SELECT *,food_id AS meal_id,name AS title,COALESCE(category,'Any') AS category,'food' AS planner_source FROM foods WHERE COALESCE(archived,0)=0 AND COALESCE(ingredient_only,0)=0 ORDER BY name COLLATE NOCASE`).filter(row=>availability.itemAvailable(row));
 const standaloneRecipes=optionalQuery(`SELECT recipe_id AS meal_id,recipe_name AS title,COALESCE(MAX(category),'Any') AS category,MAX(COALESCE(usage_designation,'standalone')) usage_designation,'recipe' AS planner_source FROM recipes WHERE COALESCE(archived,0)=0 AND COALESCE(ingredient_only,0)=0 GROUP BY recipe_id,recipe_name ORDER BY recipe_name COLLATE NOCASE`).map(recipePlannerRecord).filter(row=>availability.itemAvailable(row));
