 const pantryRows=optionalQuery(`SELECT p.*,f.calories,f.protein,f.carbs,f.fiber,f.fat,f.saturated_fat,f.sodium FROM pantry p LEFT JOIN foods f ON UPPER(f.food_id)=UPPER(p.food_id) WHERE COALESCE(p.discontinued,0)=0 AND p.on_hand='Yes' AND COALESCE(p.quantity,0)>0`);
