 const up=()=>{if(!start.current)return;const left=offset<-45,right=offset>45,wasMoved=moved.current;start.current=null;if(left){setOffset(-90);onDismiss(item)}else if(right){setOffset(90);onAccept(item)}else{setOffset(0);if(!wasMoved)onExplain(item,decision,rank)}};
