function pantryUrgency(item,referenceDate=new Date()){
 const expiration=item?.expiration?new Date(`${item.expiration}T12:00:00`):null;
 const valid=expiration&&!Number.isNaN(expiration.getTime());
 const dayMs=86400000;
 const days=valid?Math.ceil((expiration-referenceDate)/dayMs):null;
 let rank=99,label='No immediate pressure',kind='stable';
 if(days!=null&&days<0){rank=0;label=`Expired ${Math.abs(days)} day${Math.abs(days)===1?'':'s'} ago`;kind='expired'}
 else if(days===0){rank=1;label='Expires today';kind='today'}
 else if(days!=null&&days<=3){rank=2;label=`Expires in ${days} day${days===1?'':'s'}`;kind='soon'}
 else if(item?.opened==='Yes'){rank=3;label='Open package';kind='opened'}
 else if(days!=null&&days<=7){rank=4;label=`Expires in ${days} days`;kind='week'}
 else if(days!=null&&days<=14){rank=5;label=`Expires in ${days} days`;kind='later'}
 else if(Number(item?.quantity)<=1){rank=6;label='Running low';kind='low'}
 return {...item,urgencyRank:rank,urgencyLabel:label,urgencyKind:kind,daysToExpiration:days};
}
