 if(stepGap>0)priorities.push({id:'steps',category:'Health',title:`Walk ${Math.round(stepGap).toLocaleString()} more steps`,summary:'Activity remains below today’s target but is still recoverable.',why:'Your current step count is below the configured daily target.',benefit:'Supports energy balance and cardiovascular health',data:`Current ${Math.round(finite(steps)).toLocaleString()}; target ${Math.round(finite(stepTarget)).toLocaleString()}.`,action:()=>{sessionStorage.setItem('fizz-open-health-metric','steps');navigate('health')},priority:75});
