 const recipes=optionalQuery(`SELECT recipe_id,recipe_name FROM recipes WHERE COALESCE(archived,0)=0 AND COALESCE(usage_designation,'standalone') IN ('component','both') GROUP BY recipe_id,recipe_name ORDER BY recipe_name LIMIT 250`);
