function UnknownBarcodeResolver({barcode,onClose,onCreate,onLinked}){
 const [search,setSearch]=useState(''),[error,setError]=useState(''),[savingId,setSavingId]=useState(null);
 const term=`%${search.trim()}%`;
 const foods=optionalQuery(`SELECT * FROM foods WHERE COALESCE(archived,0)=0 AND (?='' OR name LIKE ? OR COALESCE(brand,'') LIKE ?) ORDER BY CASE WHEN ?<>'' AND LOWER(name)=LOWER(?) THEN 0 ELSE 1 END,name COLLATE NOCASE LIMIT 100`,[search.trim(),term,term,search.trim(),search.trim()]);
 async function link(food){
  setSavingId(food.food_id);setError('');
  try{
   await transaction(async db=>{
    const assigned=db.query(`SELECT fb.food_id,f.name FROM food_barcodes fb LEFT JOIN foods f ON UPPER(f.food_id)=UPPER(fb.food_id) WHERE fb.barcode=? LIMIT 1`,[barcode])[0];
    if(assigned&&String(assigned.food_id).toLowerCase()!==String(food.food_id).toLowerCase())throw new Error(`This barcode is already assigned to ${assigned.name||assigned.food_id}.`);
    db.run(`INSERT OR REPLACE INTO food_barcodes(barcode,food_id,created_at,updated_at) VALUES (?,?,COALESCE((SELECT created_at FROM food_barcodes WHERE barcode=?),?),?)`,[barcode,food.food_id,barcode,new Date().toISOString(),new Date().toISOString()]);
    db.run(`UPDATE foods SET barcode=CASE WHEN TRIM(COALESCE(barcode,''))='' THEN ? ELSE barcode END,updated_at=? WHERE food_id=?`,[barcode,new Date().toISOString(),food.food_id]);
   });
   onLinked(food);
  }catch(err){setError(err instanceof Error?err.message:String(err));setSavingId(null)}
 }
 return <div className="decision-page unknown-barcode-page" role="dialog" aria-modal="true"><div className="decision-page-inner"><header className="decision-detail-head"><button type="button" className="header-icon-action" onClick={onClose} aria-label="Cancel barcode assignment"><X/></button><div><small>LIBRARY</small><h2>Barcode Not Found</h2></div><span/></header><section className="decision-block unknown-barcode-summary"><small>SCANNED BARCODE</small><h3>{barcode}</h3><p>No current food uses this barcode. Choose what to do next.</p></section><section className="decision-block unknown-barcode-options"><small>CHOOSE AN OPTION</small><h3>Match to existing food</h3><p>Search your current foods and attach this barcode to the correct record.</p><label className="search unknown-barcode-search"><Search/><input autoFocus value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search current foods…"/></label><div className="barcode-match-list unknown-barcode-match-list">{foods.length?foods.map(food=><button type="button" key={food.food_id} disabled={savingId!==null} onClick={()=>link(food)}><span><b>{food.name}</b><small>{food.brand||'Brand not recorded'} · {food.default_serving||1} {food.unit||'serving'}</small></span><ChevronRight/></button>):<p>No matching foods found.</p>}</div>{error&&<div className="inline-error">{error}</div>}</section><button type="button" className="compact-action-row unknown-barcode-create" onClick={()=>onCreate(barcode)}><Plus/><span><b>Create new food</b><small>Continue to New Food with this barcode included</small></span><ChevronRight/></button><button type="button" className="compact-action-row unknown-barcode-cancel" onClick={onClose}><X/><span><b>Cancel</b><small>Return to the Library without using this barcode</small></span><ChevronRight/></button></div></div>
}

