 const availability=buildAvailabilityIndex({pantryRows:libraryPantryRows,recipeRows:optionalQuery(`SELECT recipe_id,ingredient_type,ingredient_id,ingredient_name,amount,unit FROM recipes WHERE COALESCE(archived,0)=0`),mealComponents:optionalQuery(`SELECT meal_id,component_type,component_id,component_name,optional FROM meal_components`),mealDefinitions:optionalQuery(`SELECT meal_id,source_type,source_id,track_inventory FROM meal_definitions WHERE COALESCE(archived,0)=0`)});
