 const libraryInventoryState=(type,item)=>{const id=String(type==='food'?item.food_id:type==='recipe'?`recipe:${item.recipe_id}`:item.source_id||'').toLowerCase(),name=String(item.name||item.recipe_name||item.title||'').trim().toLowerCase(),tracked=trackedFoodIds.has(id)||trackedNames.has(name),available=availableFoodIds.has(id)||availableNames.has(name);return {tracked,available}};
