const normalizeBarcode=value=>String(value||'').replace(/\D/g,'').trim();
const normalizeMatchText=value=>String(value||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,' ').trim();
function barcodeCandidates({name='',brand=''}){
 const nameTerms=normalizeMatchText(name).split(' ').filter(term=>term.length>2);
 const brandKey=normalizeMatchText(brand);
 return optionalQuery(`SELECT f.*,p.pantry_id,p.quantity AS pantry_quantity,p.unit AS pantry_unit,p.on_hand,p.status AS pantry_status
   FROM foods f LEFT JOIN pantry p ON UPPER(p.food_id)=UPPER(f.food_id) AND COALESCE(p.discontinued,0)=0
   WHERE COALESCE(f.archived,0)=0 ORDER BY f.name COLLATE NOCASE LIMIT 1000`).map(food=>{
    const foodName=normalizeMatchText(food.name),foodBrand=normalizeMatchText(food.brand||'');
    let score=0;if(brandKey&&foodBrand===brandKey)score+=50;else if(brandKey&&foodBrand.includes(brandKey))score+=30;
    for(const term of nameTerms)if(foodName.includes(term))score+=12;
    if(normalizeMatchText(name)&&foodName===normalizeMatchText(name))score+=80;
    return {...food,matchScore:score};
   }).filter(food=>food.matchScore>0).sort((a,b)=>b.matchScore-a.matchScore||String(a.name).localeCompare(String(b.name))).slice(0,8);
}

