 const record=async({code,foodId,foodName,result})=>run(`INSERT INTO barcode_scan_events(barcode,food_id,food_name,result,scanned_at) VALUES (?,?,?,?,?)`,[code,foodId||null,foodName||null,result,new Date().toISOString()]);
 const handleDetected=async raw=>{setScanning(false);const code=normalizeBarcode(raw);if(!code)return;setBarcode(code);setSession(current=>({...current,scanned:current.scanned+1}));const exact=optionalQuery(`SELECT f.*,p.pantry_id,p.quantity AS pantry_quantity,p.unit AS pantry_unit,p.on_hand,p.status AS pantry_status FROM foods f LEFT JOIN pantry p ON UPPER(p.food_id)=UPPER(f.food_id) AND COALESCE(p.discontinued,0)=0 LEFT JOIN food_barcodes fb ON UPPER(fb.food_id)=UPPER(f.food_id) WHERE (REPLACE(REPLACE(COALESCE(f.barcode,''),'-',''),' ','')=? OR fb.barcode=?) AND COALESCE(f.archived,0)=0 LIMIT 1`,[code,code])[0];if(exact){setMatches([exact]);setStage('exact');setSession(current=>({...current,matched:current.matched+1}));await record({code,foodId:exact.food_id,foodName:exact.name,result:'matched'});setRevision(x=>x+1);return}setStage('identify')};
 const searchMatches=()=>{const found=barcodeCandidates({name:productName,brand});setMatches(found);setStage('matches')};
 const ensurePantry=async food=>{const now=new Date().toISOString();await transaction(db=>{const existing=db.query(`SELECT * FROM pantry WHERE UPPER(food_id)=UPPER(?) ORDER BY COALESCE(discontinued,0),id LIMIT 1`,[food.food_id])[0];if(existing)db.run(`UPDATE pantry SET discontinued=0,on_hand='Yes',status='Active',verified_at=? WHERE id=?`,[now,existing.id]);else db.run(`INSERT INTO pantry(pantry_id,item,food_id,brand,on_hand,quantity,unit,location,status,verified_at,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?)`,[`P-${Date.now()}`,food.name,food.food_id,food.brand||null,'Yes',1,food.unit||'item','Pantry','Active',now,'Created by barcode reconciliation'])});onChanged?.();setMessage(`${food.name} is marked In Stock.`);setRevision(x=>x+1)};
 const linkFood=async food=>{const now=new Date().toISOString();await transaction(db=>{const conflict=db.query(`SELECT food_id FROM food_barcodes WHERE barcode=? AND UPPER(food_id)<>UPPER(?) LIMIT 1`,[barcode,food.food_id])[0];if(conflict)throw new Error('This barcode is already linked to another food.');db.run(`INSERT OR REPLACE INTO food_barcodes(barcode,food_id,created_at,updated_at) VALUES (?,?,COALESCE((SELECT created_at FROM food_barcodes WHERE barcode=?),?),?)`,[barcode,food.food_id,barcode,now,now]);if(!normalizeBarcode(food.barcode))db.run(`UPDATE foods SET barcode=?,updated_at=? WHERE food_id=?`,[barcode,now,food.food_id])});await ensurePantry(food);await record({code:barcode,foodId:food.food_id,foodName:food.name,result:'linked'});setSession(current=>({...current,linked:current.linked+1}));setStage('complete')};
