function PageShell({eyebrow,title,description,onBack,children}){return <><header className="settings-page-header"><button className="back-link" onClick={onBack}>‹ Back</button><Brand/><small>{eyebrow}</small><h1>{title}</h1>{description&&<p>{description}</p>}</header>{children}</>}
function downloadJson(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function AboutPage({onBack}){const db=databaseStatus(),[history,setHistory]=useState(false),latest=RELEASE_HISTORY.find(r=>r.version===VERSION)||RELEASE_HISTORY[0];return <PageShell eyebrow="ABOUT" title="Fizz Health" description="Version, diagnostics, and release history." onBack={onBack}><section className="about-summary"><div><span>Application version</span><b>{VERSION}</b><small>Issued {RELEASE_DATE}</small></div><div><span>Build identifier</span><b>{BUILD_ID}</b></div><div><span>Deployment</span><b>{DEPLOYMENT_ID}</b></div><div><span>Created</span><b>{new Date(RELEASE_CREATED_AT).toLocaleString([],{dateStyle:'medium',timeStyle:'short'})}</b></div><div><span>Schema</span><b>v{db.schemaVersion}</b><small>Issued {RELEASE_DATE}</small></div><div><span>Release ID</span><b>{DEPLOYMENT_ID}</b></div><div><span>Storage</span><b>Local SQLite</b></div></section><section className="release-notes-panel"><small>WHAT’S NEW IN v{VERSION}</small><h2>{latest.name}</h2><div className="release-scroll">{latest.stories.map(([id,title])=><div key={id}><b>{id}</b><span>{title}</span></div>)}</div><p className="testing-note"><ShieldCheck/> Use this list as the testing checklist for the current build.</p></section><button className="action" onClick={()=>setHistory(true)}><BookOpen/><div><b>View full release history</b><span>Browse every release with FH/HF numbers and timestamps</span></div><ChevronRight/></button>{history&&<div className="decision-page" role="dialog" aria-modal="true"><div className="decision-page-inner"><header className="decision-detail-head"><div><small>RELEASE HISTORY</small><h2>All releases</h2></div><button onClick={()=>setHistory(false)} aria-label="Close release history"><X/></button></header><div className="release-history">{RELEASE_HISTORY.map((r,i)=><details key={r.releaseId} open={i===0}><summary><div><b>v{r.version} · {r.name}</b><span>{new Date(r.created).toLocaleString([],{dateStyle:'medium',timeStyle:'short'})} · {r.type}</span></div><ChevronDown/></summary><div className="release-history-body"><p><b>Build:</b> {r.build} · <b>Release ID:</b> {r.releaseId}</p>{r.stories.map(([id,title])=><div className="history-story" key={id}><b>{id}</b><span>{title}</span></div>)}<p><b>Known issues:</b> {r.knownIssues.length?r.knownIssues.join('; '):'None recorded.'}</p></div></details>)}</div></div></div>}</PageShell>}
function DatabaseTransferPage({onBack,refresh}){const [status,setStatus]=useState(''),[busy,setBusy]=useState(false),workbookInput=useRef(null);async function workbook(file){if(!file)return;setBusy(true);setStatus(`Importing ${file.name}…`);try{const r=await importWorkbook(file);setStatus(`Imported ${r.foods} foods, ${r.pantry} pantry items, ${r.recipes} recipe ingredients, ${r.healthMetrics||0} health readings, ${r.labs||0} lab results, and ${r.workoutSets||0} workout sets. ${r.coverage?.length||0} workbook sheets audited.`);refresh()}catch(e){setStatus(`Import failed: ${e.message||e}`)}finally{setBusy(false)}}async function sqlite(e){const f=e.target.files?.[0];if(!f)return;setBusy(true);try{await importDatabase(await f.arrayBuffer());setStatus('Database restored and migrated successfully.');refresh()}catch(err){setStatus(`Restore failed: ${err.message||err}`)}finally{setBusy(false);e.target.value=''}}function exportDb(){const blob=new Blob([exportDatabase()],{type:'application/vnd.sqlite3'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`FizzHealth-${today()}.sqlite`;a.click();URL.revokeObjectURL(a.href)}return <PageShell eyebrow="DATA" title="Database import & export" description="Move user data without changing the database schema." onBack={onBack}>{status&&<div className="import-banner working">{status}</div>}<section className="data-section"><input ref={workbookInput} className="visually-hidden" type="file" accept=".xlsx" onChange={e=>workbook(e.target.files?.[0])}/><button className="action" disabled={busy} onClick={()=>workbookInput.current?.click()}><Upload/><div><b>Import Fizz Health workbook</b><span>Foods, pantry, recipes, health data, and history</span></div></button><button className="action" onClick={exportDb}><Download/><div><b>Export SQLite backup</b><span>Save a complete portable database</span></div></button><label className="action"><Upload/><div><b>Restore SQLite backup</b><span>Restore and migrate a previous backup</span></div><input type="file" accept=".sqlite,.db" onChange={sqlite}/></label></section></PageShell>}
function SchemaPage({onBack}){const [status,setStatus]=useState(''),input=useRef(null),db=databaseStatus();const schema=()=>({format:'fizz-health-schema',schema_version:db.schemaVersion,exported_at:new Date().toISOString(),tables:query("SELECT name,sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")});function exportSchema(){downloadJson(`FizzHealth-schema-v${db.schemaVersion}.json`,schema())}async function importSchema(file){if(!file)return;try{const data=JSON.parse(await file.text());if(data.format!=='fizz-health-schema'||!Array.isArray(data.tables))throw new Error('Not a valid Fizz Health schema JSON file.');setStatus(`Schema JSON validated: version ${data.schema_version}, ${data.tables.length} tables. No user data was changed.`)}catch(e){setStatus(`Validation failed: ${e.message||e}`)}}return <PageShell eyebrow="SCHEMA" title="Schema JSON management" description="Database structure is managed separately from user data." onBack={onBack}>{status&&<div className="import-banner working">{status}</div>}<section className="data-section"><button className="action" onClick={exportSchema}><FileJson/><div><b>Export schema JSON</b><span>Save table definitions and schema version</span></div></button><input ref={input} className="visually-hidden" type="file" accept="application/json,.json" onChange={e=>importSchema(e.target.files?.[0])}/><button className="action" onClick={()=>input.current?.click()}><Upload/><div><b>Import and validate schema JSON</b><span>Validate structure before any migration work</span></div></button><section className="schema-view"><h2>Current schema</h2><div className="release-scroll">{schema().tables.map(t=><details key={t.name}><summary>{t.name}</summary><pre>{t.sql}</pre></details>)}</div></section></section></PageShell>}
function ArchivedItemsPage({onBack,refresh}){const [kind,setKind]=useState('foods'),[q,setQ]=useState(''),[tick,setTick]=useState(0),search=`%${q}%`,foods=query('SELECT * FROM foods WHERE COALESCE(archived,0)=1 AND name LIKE ? ORDER BY archived_at DESC,name',[search]),recipes=query('SELECT recipe_id,recipe_name,MAX(archived_at) archived_at,COUNT(*) ingredient_count FROM recipes WHERE COALESCE(archived,0)=1 AND recipe_name LIKE ? GROUP BY recipe_id,recipe_name ORDER BY archived_at DESC',[search]);async function restoreFood(f){const restoredAt=new Date().toISOString();await run('UPDATE foods SET archived=0,archived_at=NULL,restored_at=?,archive_source=NULL,updated_at=? WHERE food_id=?',[restoredAt,restoredAt,f.food_id]);setTick(x=>x+1);refresh()}async function restoreRecipe(r){const restoredAt=new Date().toISOString();await run('UPDATE recipes SET archived=0,archived_at=NULL,restored_at=?,archive_source=NULL WHERE recipe_id=? OR recipe_name=?',[restoredAt,r.recipe_id,r.recipe_name]);setTick(x=>x+1);refresh()}const rows=kind==='foods'?foods:recipes;return <PageShell eyebrow="ARCHIVE" title="Archived items" description="Restore foods and recipes without changing historical meals." onBack={onBack}><div className="filter-pills"><button className={kind==='foods'?'active':''} onClick={()=>setKind('foods')}>Foods</button><button className={kind==='recipes'?'active':''} onClick={()=>setKind('recipes')}>Recipes</button></div><label className="search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder={`Search archived ${kind}…`}/></label><div className="list">{rows.map(r=><div className="item" key={r.food_id||r.recipe_id||r.recipe_name}><div><b>{r.name||r.recipe_name}</b><span>Archived {r.archived_at?new Date(r.archived_at).toLocaleString():'date unknown'}{r.ingredient_count?` · ${r.ingredient_count} ingredients`:''}</span></div><button className="restore-button" onClick={()=>kind==='foods'?restoreFood(r):restoreRecipe(r)}><RotateCcw/> Restore</button></div>)}{!rows.length&&<div className="empty">No archived {kind}.</div>}</div></PageShell>}
function MaintenancePage({onBack,refresh}){const [status,setStatus]=useState(''),[auditReport,setAuditReport]=useState(null),db=databaseStatus();function runNutritionAudit(){const audit=auditAggregateNutrition(query);setAuditReport(audit);const invalid=[...audit.recipes,...audit.meals].filter(x=>!x.valid);setStatus(invalid.length?`Aggregate nutrition audit: ${audit.valid} valid; ${audit.invalid} need attention.`:`Aggregate nutrition audit passed: all ${audit.total} active recipes and meals calculate correctly.`)}async function wipe(){if(confirm('Erase all local Fizz Health data on this device? This cannot be undone.')){await resetDatabase();setStatus('Local database erased and rebuilt.');refresh()}}return <PageShell eyebrow="MAINTENANCE" title="Maintenance & audit" description="Diagnostics and recovery tools for the local database." onBack={onBack}><section className="about-summary"><div><span>Schema</span><b>v{db.schemaVersion}</b><small>Issued {RELEASE_DATE}</small></div><div><span>Foods</span><b>{db.foods}</b></div><div><span>Pantry</span><b>{db.pantry}</b></div><div><span>Recipes</span><b>{db.recipes}</b></div><div><span>Nutrition coverage</span><b>{db.nutritionCoverage}%</b></div><div><span>Historical meals</span><b>{db.history?.total_meals||0}</b></div></section>{status&&<div className={`import-banner ${auditReport?.invalid?'warning':'success'}`}>{status}</div>}{auditReport&&auditReport.invalid>0&&<section className="data-section"><h3>Items needing attention</h3>{[...auditReport.recipes,...auditReport.meals].filter(item=>!item.valid).map(item=><article className="audit-result" key={`${item.type}-${item.id}`}><b>{item.name}</b><span>{item.type} · {item.status.replaceAll('_',' ')}</span><small>{item.issues.join(' ')}</small></article>)}</section>}<section className="data-section"><button className="action" onClick={runNutritionAudit}><ShieldCheck/><div><b>Run database audit</b><span>Calculate every active Recipe and Meal from current source nutrition</span></div></button><button className="action danger" onClick={wipe}><Trash2/><div><b>Erase local database</b><span>Use only after exporting a backup</span></div></button></section></PageShell>}
function AudioSettingsPage({onBack}){
 const supported=typeof window!=='undefined'&&'speechSynthesis' in window;
 const read=()=>{try{return JSON.parse(localStorage.getItem('fizz-audio-settings-v1')||'{}')}catch{return {}}};
 const initial=read();
 const [voices,setVoices]=useState([]),[voiceURI,setVoiceURI]=useState(initial.voiceURI||''),[rate,setRate]=useState(String(initial.rate||1)),[status,setStatus]=useState('');
 useEffect(()=>{if(!supported)return;const load=()=>setVoices(window.speechSynthesis.getVoices().filter(v=>/^en/i.test(v.lang)||!v.lang));load();window.speechSynthesis.addEventListener?.('voiceschanged',load);return()=>window.speechSynthesis.removeEventListener?.('voiceschanged',load)},[supported]);
 const duplicates=voices.reduce((a,v)=>(a[v.name]=(a[v.name]||0)+1,a),{});
 function save(nextVoice=voiceURI,nextRate=rate){const voice=voices.find(v=>voiceIdentity(v)===nextVoice);const data={voiceURI:nextVoice,voiceName:voice?.name||initial.voiceName||'',lang:voice?.lang||initial.lang||'',localService:voice?.localService??initial.localService??null,rate:Number(nextRate)||1,updatedAt:new Date().toISOString()};localStorage.setItem('fizz-audio-settings-v1',JSON.stringify(data));localStorage.setItem('fizz-brief-voice-uri',nextVoice);localStorage.setItem('fizz-brief-speech-rate',String(data.rate));setStatus('Audio settings saved and will persist across releases.');}
 function test(){if(!supported)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance('Edward, this is your selected Fizz Health narration voice.');u.rate=Number(rate)||1;const v=voices.find(x=>voiceIdentity(x)===voiceURI)||voices.find(x=>x.name===initial.voiceName&&x.lang===initial.lang)||voices.find(x=>x.default)||voices[0];if(v)u.voice=v;window.speechSynthesis.speak(u)}
 return <><div className="standard-form-header"><button type="button" onClick={onBack} aria-label="Close Audio settings"><X/></button><div><small>SETTINGS</small><h2>Audio</h2></div><button type="button" onClick={()=>save()} aria-label="Save Audio settings"><Check/></button></div><section className="audio-settings-page"><h1>Narration voice</h1><p>Choose the voice used for the Daily Brief. Fizz Health stores both the exact voice identifier and a name-and-language fallback so updates do not reset your choice.</p>{supported?<><label>Voice<select value={voiceURI} onChange={e=>{setVoiceURI(e.target.value);save(e.target.value,rate)}}><option value="">Device default</option>{voices.map(v=><option key={voiceIdentity(v)} value={voiceIdentity(v)}>{voiceLabel(v,duplicates)}</option>)}</select></label><label>Speaking speed<select value={rate} onChange={e=>{setRate(e.target.value);save(voiceURI,e.target.value)}}><option value="0.8">Slower</option><option value="1">Normal</option><option value="1.15">Faster</option><option value="1.3">Fast</option></select></label><button className="primary" onClick={test}><Volume2/> Test Voice</button></>:<div className="empty">Speech narration is not supported by this browser.</div>}{status&&<div className="status">{status}</div>}</section></>
}

function DataEnrichmentPage({onBack,refresh}){
 const [tick,setTick]=useState(0),[kind,setKind]=useState('ingredients');
 const foods=optionalQuery(`SELECT food_id AS id,name AS title,COALESCE(classification,'ingredient') classification,COALESCE(usage_designation,consumption_role,'component') usage FROM foods WHERE COALESCE(archived,0)=0 ORDER BY name COLLATE NOCASE`);
 const recipes=optionalQuery(`SELECT recipe_id AS id,recipe_name AS title,MAX(COALESCE(classification,'recipe')) classification,MAX(COALESCE(usage_designation,'standalone')) usage FROM recipes WHERE COALESCE(archived,0)=0 GROUP BY recipe_id,recipe_name ORDER BY recipe_name COLLATE NOCASE`);
 const meals=optionalQuery(`SELECT meal_id AS id,title,COALESCE(classification,'meal') classification,COALESCE(usage_designation,'standalone') usage FROM meal_definitions WHERE COALESCE(archived,0)=0 ORDER BY title COLLATE NOCASE`);
 const rows=kind==='ingredients'?foods:kind==='recipes'?recipes:meals;
 async function update(row,field,value){if(kind==='ingredients')await run(`UPDATE foods SET ${field}=?,updated_at=? WHERE food_id=?`,[value,new Date().toISOString(),row.id]);else if(kind==='recipes')await run(`UPDATE recipes SET ${field}=? WHERE recipe_id=?`,[value,row.id]);else await run(`UPDATE meal_definitions SET ${field}=?,updated_at=? WHERE meal_id=?`,[value,new Date().toISOString(),row.id]);setTick(x=>x+1);refresh?.()}
 return <PageShell eyebrow="DATA ENRICHMENT" title="Classification & Usage" description="Turn the food library into structured planning data." onBack={onBack}><div className="filter-pills">{[['ingredients','Ingredients'],['recipes','Recipes'],['meals','Meals']].map(([id,label])=><button key={id} className={kind===id?'active':''} onClick={()=>setKind(id)}>{label}</button>)}</div><div className="enrichment-list" data-tick={tick}>{rows.map(row=><article key={row.id}><div><b>{row.title}</b><small>{row.classification} · {row.usage}</small></div><select aria-label={`${row.title} classification`} value={row.classification} onChange={e=>update(row,'classification',e.target.value)}>{CLASSIFICATIONS.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><select aria-label={`${row.title} usage`} value={row.usage} onChange={e=>update(row,'usage_designation',e.target.value)}>{CONSUMPTION_ROLES.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></article>)}</div></PageShell>
}
function Data({refresh}){const [page,setPage]=useState(null);if(page==='audio')return <AudioSettingsPage onBack={()=>setPage(null)}/>;if(page==='about')return <AboutPage onBack={()=>setPage(null)}/>;if(page==='database')return <DatabaseTransferPage onBack={()=>setPage(null)} refresh={refresh}/>;if(page==='schema')return <SchemaPage onBack={()=>setPage(null)}/>;if(page==='profile')return <PersonalHealthProfile onBack={()=>setPage(null)} onClose={()=>setPage(null)}/>;if(page==='nutrients')return <NutrientConfiguration onBack={()=>setPage(null)} onClose={()=>setPage(null)}/>;if(page==='archived')return <ArchivedItemsPage onBack={()=>setPage(null)} refresh={refresh}/>;if(page==='enrichment')return <DataEnrichmentPage onBack={()=>setPage(null)} refresh={refresh}/>;if(page==='maintenance')return <MaintenancePage onBack={()=>setPage(null)} refresh={refresh}/>;const panels=[['enrichment',Sparkles,'Data Enrichment','Classify foods, recipes, and meals and complete missing data'],['audio',Volume2,'Audio & narration','Choose a Daily Brief voice, speaking speed, and persistent narration defaults'],['about',Info,'About & release notes','Version, build timestamp, diagnostics, current notes, and full history'],['database',Database,'Database import & export','Backup, restore, and workbook data transfer'],['schema',FileJson,'Schema JSON','View, export, import, and validate database structure'],['profile',UserRound,'Personal health profile','Identity-neutral health inputs, activity, smoking, and goals'],['nutrients',SlidersHorizontal,'Preferences & nutrient targets','Targets, limits, formulas, units, and dashboard behavior'],['archived',Archive,'Archived items','Restore archived foods and recipes'],['maintenance',Wrench,'Maintenance & audit','Database diagnostics, integrity checks, and reset tools']];return <><header><Brand/><small>SETTINGS</small><h1>Settings</h1><p>Choose a focused area. Tasks are grouped by purpose and kept off this hub.</p></header><section className="settings-grid">{panels.map(([id,Icon,title,desc])=><button key={id} onClick={()=>setPage(id)}><Icon/><div><b>{title}</b><span>{desc}</span></div><ChevronRight/></button>)}</section></>}

createRoot(document.getElementById('root')).render(<App/>);
